import Foundation
// Define the first data frame
let df1 = [
    ["id": 1, "name": "John", "age": 30],
    ["id": 2, "name": "Jane", "age": 25],
    ["id": 3, "name": "Bob", "age": 40]
]
// Define the second data frame
let df2 = [
    ["id": 1, "city": "New York", "country": "USA"],
    ["id": 2, "city": "Paris", "country": "France"],
    ["id": 4, "city": "Sydney", "country": "Australia"]
]
// Merge the two data frames based on the "id" column
let mergedDF = df1.merge(with: df2, on: "id")
// Print the resulting data frame
print(mergedDF)
```
In this example, we have two data frames (`df1` and `df2`) with a common "id" column. We use the `merge` function to merge them based on the "id" column, and the resulting data frame (`mergedDF`) will contain all the columns from both data frames, but only the rows where the "id" values match.
