$sql = "SELECT date, injured, killed FROM gun_violence WHERE gun_type = 'assault weapon' AND mass_shooting = true AND date >= '2010-01-01' ORDER BY date ASC";
$result = $conn->query($sql);
// Calculate the average number of casualties per incident
$total_casualties = 0;
$num_incidents = 0;
if ($result->num_rows > 0) {
    while($row = $result->fetch_assoc()) {
        $injured = $row["injured"];
        $killed = $row["killed"];
        $total_casualties += $injured + $killed;
        $num_incidents++;
    }
}
$average_casualties = $total_casualties / $num_incidents;
