  "(`$50,000 to $100,000` / total_revenue) as `$50,000 to $100,000 %`", "(`$100,000 to $250,000` / total_revenue) as `$100,000 to $250,000 %`",
  "(`$250,000 or more` / total_revenue) as `$250,000 or more %`")
// Create a bar chart of tax revenue by industry
