    {
        // Connection string to your database
        string connectionString = "Data Source=your_server;Initial Catalog=your_database;Integrated Security=True";
        // SQL query to retrieve all animals that live in dense tropical rainforests
        string query = "SELECT * FROM animals WHERE habitat = 'dense tropical rainforest'";
        // Create a list to store the animal species
        List<string> animalSpecies = new List<string>();
        // Create a dictionary to categorize the animal species by classification
        Dictionary<string, List<string>> animalClassification = new Dictionary<string, List<string>>()
