            {"Mammals", new List<string>()},
            {"Birds", new List<string>()},
            {"Reptiles", new List<string>()},
            {"Amphibians", new List<string>()},
            {"Insects", new List<string>()}
        };
        // Connect to the database and execute the query
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            SqlCommand command = new SqlCommand(query, connection);
            connection.Open();
            SqlDataReader reader = command.ExecuteReader();
            // Loop through the records and add the animal species to the list and dictionary
            while (reader.Read())
            {
                string species = reader["species"].ToString();
                string classification = reader["classification"].ToString();
                animalSpecies.Add(species);
                if (animalClassification.ContainsKey(classification))
