<script>
function generatePassword() {
  var length = document.getElementById("length").value;
  var uppercase = document.getElementById("uppercase").checked;
  var lowercase = document.getElementById("lowercase").checked;
  var numbers = document.getElementById("numbers").checked;
  var special = document.getElementById("special").checked;
  var uppercase_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  var lowercase_chars = "abcdefghijklmnopqrstuvwxyz";
  var number_chars = "0123456789";
  var special_chars = "!@#$%^&*()";
  var all_chars = "";
  var password = "";
  if (uppercase) {
    all_chars += uppercase_chars;
    password += uppercase_chars.charAt(Math.floor(Math.random() * uppercase_chars.length));
    password += uppercase_chars.charAt(Math.floor(Math.random() * uppercase_chars.length));
  }
  if (lowercase) {
    all_chars += lowercase_chars;
    password += lowercase_chars.charAt(Math.floor(Math.random() * lowercase_chars.length));
    password += lowercase_chars.charAt(Math.floor(Math.random() * lowercase_chars.length));
  }
  if (numbers) {
    all_chars += number_chars;
    password += number_chars.charAt(Math.floor(Math.random() * number_chars.length));
    password += number_chars.charAt(Math.floor(Math.random() * number_chars.length));
  }
  if (special) {
    all_chars += special_chars;
    password += special_chars.charAt(Math.floor(Math.random() * special_chars.length));
    password += special_chars.charAt(Math.floor(Math.random() * special_chars.length));
  }
  while (password.length < length) {
    password += all_chars.charAt(Math.floor(Math.random() * all_chars.length));
  }
  password = password.split('').sort(function(){return 0.5-Math.random()}).join('');
  document.getElementById("password").value = password;
}
